def wait(seconds, **_extra):
    import json, os, datetime, time, uuid, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _minute_trunc(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _record_call(api_key_id, status, error_code=None):
        # "Observability": append to wait_requests.json as a call log is not defined;
        # use rate_limit_windows.json / wait_requests.json only. We persist an audit-like no-op
        # by updating updated_at on the api_key if present.
        api_keys = _load("api_keys.json")
        if api_key_id:
            for k in api_keys:
                if k.get("id") == api_key_id:
                    k["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("api_keys.json", api_keys)
        return None

    # Validate seconds
    if seconds is None:
        return _err("VALIDATION_ERROR", "`seconds` is required", field="seconds")
    if not isinstance(seconds, (int, float)) or isinstance(seconds, bool):
        return _err("VALIDATION_ERROR", "`seconds` must be a number", field="seconds")
    if seconds < 0 or seconds > 300:
        return _err("VALIDATION_ERROR", "`seconds` must be between 0 and 300", field="seconds")

    # Authenticate ambient: find an active key that can serve this request
    api_keys = _load("api_keys.json")
    active_keys = []
    for k in api_keys:
        if k.get("status") == "active":
            rl = k.get("rate_limit_per_minute")
            mx = k.get("max_seconds_per_request")
            if isinstance(rl, int) and 1 <= rl <= 6000 and isinstance(mx, (int, float)) and 0 <= mx <= 300:
                active_keys.append(k)
    if not active_keys:
        _record_call(None, "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this operation")

    # Choose a key that allows this seconds
    api_key = None
    for k in active_keys:
        if seconds <= float(k.get("max_seconds_per_request", 0)):
            api_key = k
            break
    if api_key is None:
        # still an authorization-ish failure in this model: no key can satisfy prerequisites
        _record_call(None, "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key permits the requested seconds")

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = _iso(now)
    api_key_id = api_key["id"]

    # Idempotency: if caller provided client_request_id via _extra (gateway), honor it
    client_request_id = _extra.get("client_request_id")
    if client_request_id is not None:
        if not isinstance(client_request_id, str) or not (1 <= len(client_request_id) <= 200):
            _record_call(api_key_id, "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "`client_request_id` must be a non-empty string up to 200 chars", field="client_request_id")
        wait_reqs = _load("wait_requests.json")
        for r in wait_reqs:
            if r.get("api_key_id") == api_key_id and r.get("client_request_id") == client_request_id:
                # Idempotent: return existing row, do not re-run
                _record_call(api_key_id, "ok")
                return {"wait_request": r}

    # Create queued wait request
    wait_reqs = _load("wait_requests.json")
    req_id = "wr_" + uuid.uuid4().hex
    queued = {
        "id": req_id,
        "api_key_id": api_key_id,
        "seconds": float(seconds),
        "status": "queued",
        "requested_at": now_iso,
        "started_at": None,
        "completed_at": None,
        "actual_elapsed_ms": None,
        "error_code": None,
        "error_message": None,
        "client_request_id": client_request_id,
        "request_ip": _extra.get("request_ip"),
        "user_agent": _extra.get("user_agent"),
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce unique(api_key_id, client_request_id) where client_request_id not null
    if client_request_id is not None:
        for r in wait_reqs:
            if r.get("api_key_id") == api_key_id and r.get("client_request_id") == client_request_id:
                _record_call(api_key_id, "ok")
                return {"wait_request": r}

    wait_reqs.append(queued)
    _save("wait_requests.json", wait_reqs)

    # Before transitioning to running: increment/create rate_limit_windows for current minute and enforce limit
    rl_windows = _load("rate_limit_windows.json")
    window_start = _minute_trunc(now)
    window_start_iso = _iso(window_start)

    window = None
    for w in rl_windows:
        if w.get("api_key_id") == api_key_id and w.get("window_start") == window_start_iso:
            window = w
            break

    if window is None:
        window = {
            "id": "rlw_" + uuid.uuid4().hex,
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "request_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
            # schema mentions lifecycle but fields list doesn't include status; do not add extra fields
        }
        rl_windows.append(window)

    # increment and check
    limit = api_key.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        # service misconfiguration -> fail this request
        # Mark failed per rules
        for r in wait_reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["started_at"] = None
                r["completed_at"] = now_iso
                r["actual_elapsed_ms"] = 0
                r["error_code"] = "CONFIG_ERROR"
                r["error_message"] = "Invalid API key rate limit configuration"
                r["updated_at"] = now_iso
                break
        _save("wait_requests.json", wait_reqs)
        _save("rate_limit_windows.json", rl_windows)
        _record_call(api_key_id, "error", error_code="CONFIG_ERROR")
        return _err("VALIDATION_ERROR", "Invalid API key configuration")

    new_count = int(window.get("request_count", 0)) + 1
    if new_count > limit:
        # reject with rate limit error and do not start running; keep queued row but mark failed for outcome visibility
        window["updated_at"] = now_iso
        _save("rate_limit_windows.json", rl_windows)

        for r in wait_reqs:
            if r.get("id") == req_id:
                # queued -> failed is allowed
                r["status"] = "failed"
                r["completed_at"] = now_iso
                r["actual_elapsed_ms"] = 0
                r["error_code"] = "RATE_LIMIT"
                r["error_message"] = "Rate limit exceeded"
                r["updated_at"] = now_iso
                break
        _save("wait_requests.json", wait_reqs)

        _record_call(api_key_id, "error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit, window_start=window_start_iso, request_count=new_count)

    window["request_count"] = new_count
    window["updated_at"] = now_iso
    _save("rate_limit_windows.json", rl_windows)

    # Transition queued -> running
    started = datetime.datetime.now(datetime.timezone.utc)
    started_iso = _iso(started)
    for r in wait_reqs:
        if r.get("id") == req_id:
            if r.get("status") != "queued":
                _record_call(api_key_id, "error", error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Wait request is not in queued state")
            r["status"] = "running"
            r["started_at"] = started_iso
            r["updated_at"] = started_iso
            break
    else:
        _record_call(api_key_id, "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Wait request not found")

    _save("wait_requests.json", wait_reqs)

    # Perform the wait
    try:
        if seconds > 0:
            time.sleep(float(seconds))
        ended = datetime.datetime.now(datetime.timezone.utc)
        ended_iso = _iso(ended)
        actual_ms = int(max(0, round((ended - started).total_seconds() * 1000)))

        # Transition running -> completed
        for r in wait_reqs:
            if r.get("id") == req_id:
                if r.get("status") != "running":
                    _record_call(api_key_id, "error", error_code="INVALID_TRANSITION")
                    return _err("INVALID_TRANSITION", "Wait request is not in running state")
                r["status"] = "completed"
                r["completed_at"] = ended_iso
                r["actual_elapsed_ms"] = actual_ms
                r["updated_at"] = ended_iso
                break
        _save("wait_requests.json", wait_reqs)
        _record_call(api_key_id, "ok")
        # return the row
        for r in wait_reqs:
            if r.get("id") == req_id:
                return {"wait_request": r}
        return _err("NOT_FOUND", "Wait request not found after completion")
    except Exception as e:
        # Internal error: mark failed
        ended = datetime.datetime.now(datetime.timezone.utc)
        ended_iso = _iso(ended)
        for r in wait_reqs:
            if r.get("id") == req_id:
                # running -> failed allowed
                r["status"] = "failed"
                r["completed_at"] = ended_iso
                r["actual_elapsed_ms"] = int(max(0, round((ended - started).total_seconds() * 1000))) if 'started' in locals() else 0
                r["error_code"] = "INTERNAL_ERROR"
                r["error_message"] = str(e)
                r["updated_at"] = ended_iso
                break
        _save("wait_requests.json", wait_reqs)
        _record_call(api_key_id, "error", error_code="INTERNAL_ERROR")
        return _err("VALIDATION_ERROR", "Internal error while waiting", detail=str(e))

def create_api_key(name, rate_limit_per_minute=None, max_seconds_per_request=None, **_extra):
    import json, os, datetime, time, uuid, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # Validate name
    if name is None or not isinstance(name, str):
        return _err("VALIDATION_ERROR", "`name` is required and must be a string", field="name")
    nm = name.strip()
    if len(nm) < 1 or len(nm) > 200:
        return _err("VALIDATION_ERROR", "`name` must be 1..200 characters", field="name")

    # Defaults (must satisfy schema constraints)
    if rate_limit_per_minute is None:
        rate_limit_per_minute = 60
    if max_seconds_per_request is None:
        max_seconds_per_request = 300

    if not isinstance(rate_limit_per_minute, int) or isinstance(rate_limit_per_minute, bool):
        return _err("VALIDATION_ERROR", "`rate_limit_per_minute` must be an integer", field="rate_limit_per_minute")
    if rate_limit_per_minute < 1 or rate_limit_per_minute > 6000:
        return _err("VALIDATION_ERROR", "`rate_limit_per_minute` must be between 1 and 6000", field="rate_limit_per_minute")

    if not isinstance(max_seconds_per_request, int) or isinstance(max_seconds_per_request, bool):
        return _err("VALIDATION_ERROR", "`max_seconds_per_request` must be an integer", field="max_seconds_per_request")
    if max_seconds_per_request < 0 or max_seconds_per_request > 300:
        return _err("VALIDATION_ERROR", "`max_seconds_per_request` must be between 0 and 300", field="max_seconds_per_request")

    # Create plaintext key exactly once; store only a hash
    plaintext = "wait_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    api_keys = _load("api_keys.json")
    # uniqueness on key_hash
    for k in api_keys:
        if k.get("key_hash") == key_hash:
            # extremely unlikely; regenerate once
            plaintext = "wait_" + secrets.token_urlsafe(32)
            key_hash = hashlib.sha256(plaintext.encode("utf-8")).hexdigest()
            break
    for k in api_keys:
        if k.get("key_hash") == key_hash:
            return _err("CONFLICT", "Generated API key collided; please retry")

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = _iso(now)
    rec = {
        "id": "key_" + uuid.uuid4().hex,
        "key_hash": key_hash,
        "name": nm,
        "status": "active",
        "rate_limit_per_minute": rate_limit_per_minute,
        "max_seconds_per_request": max_seconds_per_request,
        "created_at": now_iso,
        "updated_at": now_iso,
        "revoked_at": None,
    }
    api_keys.append(rec)
    _save("api_keys.json", api_keys)

    return {"api_key": rec, "plaintext_api_key": plaintext}

def list_wait_requests(status=None, client_request_id=None, requested_after=None, requested_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # Validate filters
    allowed_status = {"queued", "running", "completed", "cancelled", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "`status` must be one of queued,running,completed,cancelled,failed", field="status")

    if client_request_id is not None:
        if not isinstance(client_request_id, str) or not (1 <= len(client_request_id) <= 200):
            return _err("VALIDATION_ERROR", "`client_request_id` must be 1..200 chars", field="client_request_id")

    ra = _parse_dt(requested_after) if requested_after is not None else None
    if requested_after is not None and ra is None:
        return _err("VALIDATION_ERROR", "`requested_after` must be RFC3339 date-time", field="requested_after")
    rb = _parse_dt(requested_before) if requested_before is not None else None
    if requested_before is not None and rb is None:
        return _err("VALIDATION_ERROR", "`requested_before` must be RFC3339 date-time", field="requested_before")
    if ra and rb and rb < ra:
        return _err("VALIDATION_ERROR", "`requested_before` must be >= requested_after")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "`limit` must be an integer between 1 and 200", field="limit")

    # Authenticate ambient: pick an active key (listing is per authenticated key)
    api_keys = _load("api_keys.json")
    api_key = None
    for k in api_keys:
        if k.get("status") == "active":
            api_key = k
            break
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available")

    api_key_id = api_key["id"]

    # Cursor: base64 JSON like {"ts": "...", "id": "..."}
    after_ts = None
    after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "`cursor` must be a non-empty string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        if not isinstance(obj, dict) or "ts" not in obj or "id" not in obj:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        after_ts = _parse_dt(obj.get("ts"))
        after_id = obj.get("id")
        if after_ts is None or not isinstance(after_id, str) or not after_id:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # Read and filter
    wait_reqs = _load("wait_requests.json")
    rows = []
    for r in wait_reqs:
        if r.get("api_key_id") != api_key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if client_request_id is not None and r.get("client_request_id") != client_request_id:
            continue
        rdt = _parse_dt(r.get("requested_at"))
        if rdt is None:
            continue
        if ra and rdt < ra:
            continue
        if rb and rdt > rb:
            continue
        rows.append(r)

    # Sort newest first by requested_at, tie-breaker id desc
    def _key(r):
        dt = _parse_dt(r.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    rows.sort(key=_key, reverse=True)

    # Apply cursor (start after the cursor item in this sorted order)
    if after_ts is not None:
        filtered = []
        for r in rows:
            dt = _parse_dt(r.get("requested_at"))
            rid = r.get("id")
            if dt is None or rid is None:
                continue
            # since descending: include items strictly older than cursor timestamp,
            # or same timestamp but id < cursor id (lexicographically) to avoid duplicates
            if dt < after_ts:
                filtered.append(r)
            elif dt == after_ts and isinstance(rid, str) and rid < after_id:
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("requested_at"))
        if last_dt is not None and last.get("id"):
            payload = {"ts": _iso(last_dt), "id": last["id"]}
            next_cursor = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8").rstrip("=")

    # Observability: touch api_key updated_at
    now_iso = _iso(datetime.datetime.now(datetime.timezone.utc))
    for k in api_keys:
        if k.get("id") == api_key_id:
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {
        "wait_requests": page,
        "meta": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_wait_request(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if getattr(dt, "tzinfo", None) is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        # deterministic enough for local datastore: timestamp + pid + monotonic fragment
        ts = int(_now().timestamp() * 1000)
        pid = os.getpid()
        frag = int(time.time_ns() % 1000000)
        return f"{prefix}_{ts}_{pid}_{frag}"

    def _append_log(endpoint, api_key_id, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("log"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "timestamp": _iso(_now()),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "get_wait_request"
    api_key_id_for_log = None

    # Validate input
    if not isinstance(id, str) or not id.strip():
        out = _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "field": "id"})
        return out
    rid = id.strip()

    wait_reqs = _load("wait_requests.json")
    if not isinstance(wait_reqs, list):
        wait_reqs = []

    req = None
    for r in wait_reqs:
        if isinstance(r, dict) and r.get("id") == rid:
            req = r
            break

    # Must not refuse valid requests due to missing ambient auth context.
    # If the record exists, return it; if it doesn't, return NOT_FOUND.
    if req is None:
        out = _err("NOT_FOUND", "Wait request not found.", id=rid)
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "id": rid})
        return out

    api_key_id_for_log = req.get("api_key_id")
    # If an API key is referenced, ensure it exists and is active; otherwise refuse.
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if isinstance(api_key_id_for_log, str) and api_key_id_for_log:
        key_row = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id_for_log:
                key_row = k
                break
        if key_row is None:
            out = _err("UNAUTHORIZED", "API key for this wait request no longer exists.", api_key_id=api_key_id_for_log)
            _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
            return out
        if key_row.get("status") != "active":
            out = _err("UNAUTHORIZED", "API key is not active.", api_key_id=api_key_id_for_log, status=key_row.get("status"))
            _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
            return out

    out = {"data": req}
    _append_log(endpoint, api_key_id_for_log, "ok", (time.time() - t0) * 1000, {"id": rid})
    return out

def cancel_wait_request(id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if getattr(dt, "tzinfo", None) is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        ts = int(_now().timestamp() * 1000)
        pid = os.getpid()
        frag = int(time.time_ns() % 1000000)
        return f"{prefix}_{ts}_{pid}_{frag}"

    def _append_log(endpoint, api_key_id, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("log"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "timestamp": _iso(_now()),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "cancel_wait_request"
    api_key_id_for_log = None

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        out = _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "field": "id"})
        return out
    rid = id.strip()

    if reason is not None:
        if not isinstance(reason, str):
            out = _err("VALIDATION_ERROR", "Parameter 'reason' must be a string when provided.", field="reason")
            _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "field": "reason"})
            return out
        if len(reason) > 500:
            out = _err("VALIDATION_ERROR", "Parameter 'reason' must be at most 500 characters.", field="reason", maxLength=500)
            _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "field": "reason"})
            return out

    wait_reqs = _load("wait_requests.json")
    if not isinstance(wait_reqs, list):
        wait_reqs = []

    idx = None
    req = None
    for i, r in enumerate(wait_reqs):
        if isinstance(r, dict) and r.get("id") == rid:
            idx = i
            req = r
            break

    if req is None:
        out = _err("NOT_FOUND", "Wait request not found.", id=rid)
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "id": rid})
        return out

    api_key_id_for_log = req.get("api_key_id")

    # Enforce api key existence + active
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(api_key_id_for_log, str) or not api_key_id_for_log:
        out = _err("UNAUTHORIZED", "Wait request is missing api_key_id and cannot be authorized.", id=rid)
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        return out

    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id_for_log:
            key_row = k
            break
    if key_row is None:
        out = _err("UNAUTHORIZED", "API key for this wait request no longer exists.", api_key_id=api_key_id_for_log)
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        return out
    if key_row.get("status") != "active":
        out = _err("UNAUTHORIZED", "API key is not active.", api_key_id=api_key_id_for_log, status=key_row.get("status"))
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        return out

    status = req.get("status")
    allowed_transitions = {"queued": {"running", "cancelled", "failed"}, "running": {"completed", "cancelled", "failed"},
                           "completed": set(), "cancelled": set(), "failed": set()}

    if status not in allowed_transitions:
        out = _err("VALIDATION_ERROR", "Wait request has an invalid status.", id=rid, status=status)
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        return out

    if "cancelled" not in allowed_transitions.get(status, set()):
        # already terminal
        out = _err(
            "INVALID_TRANSITION",
            "Cannot cancel a wait request that is already completed/cancelled/failed.",
            id=rid,
            status=status,
            to_status="cancelled",
        )
        _append_log(endpoint, api_key_id_for_log, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"], "status": status})
        return out

    now_iso = _iso(_now())
    # perform mutation
    updated = dict(req)
    updated["status"] = "cancelled"
    updated["completed_at"] = now_iso
    updated["updated_at"] = now_iso
    # Optional: store reason in an auditable place without violating schema; schema doesn't include cancel_reason.
    # Put it in error_message only if consistent with business rules? That would violate constraint (error_message => failed).
    # So we log it only.
    wait_reqs[idx] = updated
    _save("wait_requests.json", wait_reqs)

    _append_log(endpoint, api_key_id_for_log, "ok", (time.time() - t0) * 1000, {"id": rid, "from_status": status, "reason": reason} if reason else {"id": rid, "from_status": status})
    return {"data": updated}

def get_usage(window_start=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _truncate_minute(dt):
        return dt.replace(second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, api_key_id, status, latency_ms, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("log"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "get_usage"

    # Validate input
    dt = None
    if window_start is not None:
        if not isinstance(window_start, str):
            out = _err("VALIDATION_ERROR", "Parameter 'window_start' must be an RFC3339 datetime string if provided.")
            try:
                _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
            except Exception:
                pass
            return out
        dt = _parse_dt(window_start)
        if dt is None:
            out = _err("VALIDATION_ERROR", "Parameter 'window_start' must be a valid RFC3339 datetime string.")
            try:
                _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
            except Exception:
                pass
            return out
    else:
        dt = _now()

    window = _truncate_minute(dt)

    # Ambient auth: choose an active API key.
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        # If there are keys but none active, treat as missing/invalid for usage.
        any_keys = [k for k in api_keys if isinstance(k, dict) and isinstance(k.get("id"), str)]
        if any_keys:
            out = _err("UNAUTHORIZED", "API key is not active.")
        else:
            out = _err("UNAUTHORIZED", "API key is missing or invalid.")
        try:
            _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    api_key = active_keys[0]

    # Compute current window usage
    windows = _load("rate_limit_windows.json")
    window_iso = _iso(window)
    usage_row = None
    for w in windows:
        if not isinstance(w, dict):
            continue
        if w.get("api_key_id") == api_key.get("id") and w.get("window_start") == window_iso:
            usage_row = w
            break

    request_count = int(usage_row.get("request_count")) if usage_row and isinstance(usage_row.get("request_count"), int) else 0
    limit = api_key.get("rate_limit_per_minute")
    try:
        limit_int = int(limit)
    except Exception:
        limit_int = None

    resp = {
        "data": {
            "api_key": {
                "id": api_key.get("id"),
                "name": api_key.get("name"),
                "status": api_key.get("status"),
                "rate_limit_per_minute": api_key.get("rate_limit_per_minute"),
                "max_seconds_per_request": api_key.get("max_seconds_per_request"),
                "created_at": api_key.get("created_at"),
                "updated_at": api_key.get("updated_at"),
                "revoked_at": api_key.get("revoked_at"),
            },
            "window": {
                "window_start": window_iso,
                "request_count": request_count,
                "rate_limit_per_minute": api_key.get("rate_limit_per_minute"),
                "remaining": (max(0, limit_int - request_count) if isinstance(limit_int, int) else None),
            },
        }
    }

    try:
        _log(endpoint, api_key.get("id"), "ok", (time.time() - t0) * 1000, {"window_start": window_iso})
    except Exception:
        pass
    return resp

def revoke_api_key(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0183000" if __import__("os").path.isdir("./environment_mix/0183000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, api_key_id, status, latency_ms, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("log"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "revoke_api_key"

    # Validate input
    if not isinstance(id, str) or not id.strip():
        out = _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.")
        try:
            _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    api_keys = _load("api_keys.json")

    target = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == id:
            target = k
            break

    if target is None:
        out = _err("NOT_FOUND", "API key not found.")
        try:
            _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    # Ambient auth: authorize only if the caller is the same key (or no other auth context exists).
    # Since no explicit credential is passed, we can only allow revoking if the target is an active key
    # and it is the one we can treat as "current" (i.e., it is active and usable).
    current_candidates = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not current_candidates:
        out = _err("UNAUTHORIZED", "No active API key available for this call.")
        try:
            _log(endpoint, target.get("id"), "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    # Must be authorized to revoke it: only allow if target is one of the active candidates (self-revoke).
    authorized = any(k.get("id") == target.get("id") for k in current_candidates)
    if not authorized:
        out = _err("UNAUTHORIZED", "Not authorized to revoke this API key.")
        try:
            _log(endpoint, target.get("id"), "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    status = target.get("status")
    if status not in ("active", "revoked"):
        out = _err("VALIDATION_ERROR", "API key has invalid status.")
        try:
            _log(endpoint, target.get("id"), "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    if status == "revoked":
        out = _err("INVALID_TRANSITION", "API key is already revoked.")
        try:
            _log(endpoint, target.get("id"), "error", (time.time() - t0) * 1000, {"code": out["error"]["code"]})
        except Exception:
            pass
        return out

    # Transition active -> revoked
    now = _now()
    target["status"] = "revoked"
    target["revoked_at"] = _iso(now)
    target["updated_at"] = _iso(now)

    # Enforce constraint: revoked_at is null OR status=revoked (satisfied), and lifecycle transition permitted.
    _save("api_keys.json", api_keys)

    resp = {
        "data": {
            "id": target.get("id"),
            "name": target.get("name"),
            "status": target.get("status"),
            "rate_limit_per_minute": target.get("rate_limit_per_minute"),
            "max_seconds_per_request": target.get("max_seconds_per_request"),
            "created_at": target.get("created_at"),
            "updated_at": target.get("updated_at"),
            "revoked_at": target.get("revoked_at"),
        }
    }

    try:
        _log(endpoint, target.get("id"), "ok", (time.time() - t0) * 1000, {"revoked": True})
    except Exception:
        pass
    return resp
